import{_ as t,o as a,c as o,a3 as c}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"构建分析","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"构建分析 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/features/build-profiling"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/features/build-profiling"}]]},"headers":[],"relativePath":"zh/catter/features/build-profiling.md","filePath":"zh/catter/features/build-profiling.md","lastUpdated":1793214814000}'),r={name:"zh/catter/features/build-profiling.md"};function d(i,e,n,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="构建分析" tabindex="-1">构建分析 <a class="header-anchor" href="#构建分析" aria-label="Permalink to &quot;构建分析&quot;">​</a></h1><p><code>profile</code> 记录构建中每条命令何时启动、运行了多久、由哪条命令启动，并把它们写成一份 <a href="https://ui.perfetto.dev" target="_blank" rel="noreferrer">Perfetto</a> 和 <code>chrome://tracing</code> 都能打开的 trace：构建的时间线，从中可以看到同时运行了多少条命令、决定构建时长的那串步骤，以及耗时最长的步骤。</p><p>命令：<code>profile</code></p><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options] -- </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build-command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><code>-o, --output &lt;path&gt;</code></td><td>把 trace 写到该路径，相对路径从 <code>-C</code> 指定的目录算起。默认：<code>trace.json</code>。</td></tr><tr><td><code>--top &lt;n&gt;</code></td><td>列出耗时最长的 n 条命令。默认：5；<code>0</code> 表示不列出。</td></tr><tr><td><code>-q, --quiet</code></td><td>不打印摘要，也不打印 catter 未能捕获某条命令的原因。</td></tr></tbody></table><p><code>profile</code> 也接受所有运行构建的命令共有的选项：<code>-C</code>、<code>--capture</code>、<code>--from</code> 和 handler 的选项（见<a href="./../guide/configuration">配置参考</a>）。</p><p>构建结束后，无论成功还是失败，catter 都会写出 trace，所在目录不存在时先创建它，随后像构建那样退出。trace 无法写入时，catter 说明原因并以 1 退出；被 handler 中止的构建不生成 trace。除非指定了 <code>-q</code>，catter 一得知某条命令未能捕获，就打印原因。</p><h2 id="trace-文件" tabindex="-1">Trace 文件 <a class="header-anchor" href="#trace-文件" aria-label="Permalink to &quot;Trace 文件&quot;">​</a></h2><p>trace 是一个 JSON 文件，采用 Chrome 的 trace event 格式。在 <a href="https://ui.perfetto.dev" target="_blank" rel="noreferrer">ui.perfetto.dev</a>（Open trace file）或 <code>chrome://tracing</code>（Load）中打开它。其中的时间以微秒计，从第一条命令启动时算起。</p><ul><li><strong>泳道。</strong> 每条命令是某条泳道（lane）上的一个切片（slice）。一条命令如果在启动它的命令运行期间开始并结束，而且那条命令启动的命令从没有两条同时运行，它就画在那条命令之内、同一条泳道上：例如 shell 和它运行的编译器，编译器驱动程序和它的各个阶段（<code>cc1plus</code>、<code>as</code>、<code>collect2</code>、<code>ld</code>）。构建工具同时运行的命令，各自放在它们启动时没有任何命令在运行的第一条泳道上：在 <code>make -j8</code> 下，lane 1 是 <code>make</code>，它下面的泳道是它的任务，同时运行了几个任务就有几条。</li><li><strong>critical path。</strong> 泳道上方的一条轨道（track），放着关键路径上的命令（见下文）。</li><li><strong>running。</strong> 一个计数器（counter），显示每一时刻有多少条命令在工作。命令在运行、且它启动的命令都没有在运行时，才算在工作；catter 分析的编译器或归档工具命令则在整个运行期间都算在工作，它启动的程序也算在它里面。</li></ul><p>每个切片以它的程序命名，catter 分析的命令还带上它所涉及的文件：编译命令编译的源文件（<code>c++ main.cc</code>），链接或归档命令生成的文件（<code>c++ app</code>、<code>ar libfoo.a</code>）。catter 分析的命令，切片的类别（category）是命令所做的事：<code>compile</code>、<code>link</code>、<code>preprocess</code>、<code>archive</code> 等。切片的参数（args）包括：</p><table tabindex="0"><thead><tr><th>参数</th><th>内容</th></tr></thead><tbody><tr><td><code>command</code></td><td>命令的参数，写在一行里：只含 ASCII 字母、数字和 <code>_@%+=:,./\\-</code> 的参数原样写出，其他参数写成 JSON 字符串。</td></tr><tr><td><code>cwd</code></td><td>命令运行所在的目录。</td></tr><tr><td><code>exit</code></td><td>命令的退出码；被信号结束的命令为 128 加信号编号。</td></tr><tr><td><code>id</code></td><td>命令在会话中的 ID，<code>parent</code> 引用的就是它。</td></tr><tr><td><code>parent</code></td><td>启动它的那条命令的 ID；构建命令没有此项。</td></tr><tr><td><code>writes</code></td><td>catter 分析的命令写出的文件。</td></tr><tr><td><code>target</code></td><td>对编译命令，是读取它的目标文件的命令所写出的文件：该目标文件最终进入的库或程序。</td></tr></tbody></table><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>除非指定了 <code>-q</code>，catter 写完 trace 后会打印 trace 显示的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Profiled 1234 commands in 83.4 s: 6.2 ran at once on average, 16 at most.</span></span>
<span class="line"><span>Critical path, 48.9 s: c++ big.cc 41.0 s &gt; ar libcore.a 400 ms &gt; c++ app 7.5 s</span></span>
<span class="line"><span>Slowest:</span></span>
<span class="line"><span>  41.0 s  c++ big.cc</span></span>
<span class="line"><span>   7.5 s  c++ app</span></span>
<span class="line"><span>   3.1 s  python3</span></span>
<span class="line"><span>   2.9 s  c++ parser.cc</span></span>
<span class="line"><span>   2.0 s  cmake</span></span>
<span class="line"><span>Trace saved to /src/project/trace.json: open it in https://ui.perfetto.dev or chrome://tracing.</span></span></code></pre></div><ul><li><strong>第一行</strong>给出构建用了多久，从第一条命令启动到最后一条命令结束；平均同时有多少条命令在工作，即各条命令工作时间之和除以构建用时；以及最多同时有多少条命令在工作。</li><li><strong>关键路径</strong>是由编译、归档和链接组成的一条链，链上每一步都读取前一步写出的文件，且各步耗时之和最长。它追踪的文件是编译器或归档工具的参数中指定的文件：catter 不分析的程序（例如代码生成器）以及编译包含的头文件都不在其中，因此这条链可能比真正决定构建时长的那条短。超过六步的路径只显示前三步和最后两步。</li><li><strong>最慢的</strong>命令是工作时间最长的那些命令。构建工具、shell 或脚本只计入它自己工作的时间：例如 <code>make</code> 读取 makefile、<code>cmake</code> 配置项目的时间，而不计它们等待的编译。</li><li>有命令没有写进 trace 时，另有一行说明有多少条：catter 未能捕获的命令，以及在构建结束前没有结束的命令，例如比构建活得更久的构建服务器。</li></ul><h2 id="时间与捕获后端" tabindex="-1">时间与捕获后端 <a class="header-anchor" href="#时间与捕获后端" aria-label="Permalink to &quot;时间与捕获后端&quot;">​</a></h2><p>每个捕获后端都会给出每条命令的启动时间和时长：</p><table tabindex="0"><thead><tr><th>后端</th><th>启动时间和时长</th></tr></thead><tbody><tr><td><code>hook</code></td><td>在 Linux 和 macOS 上，由 <code>catter-proxy</code> 测量每条命令，从它启动 catter 让它运行的程序算起，到该程序退出为止；在 Windows 上由 catter 测量，从它接手钩子启动后挂起的程序算起，到该程序退出为止。构建的每个程序都要等到 catter 做出决定才启动，在 Linux 和 macOS 上还要经由 <code>catter-proxy</code> 启动：trace 显示的是构建在 catter 下运行的样子。</td></tr><tr><td><code>wrapper</code></td><td>与 <code>hook</code> 下相同，但只针对 shim 所代替的编译器、链接器和归档工具，以及构建命令：trace 中只有这些命令。</td></tr><tr><td><code>ptrace</code></td><td>catter 的跟踪者（tracer）看到每个进程 exec 它的程序以及退出的时刻。构建的每个进程在每次 fork、exec 和退出时都会暂停，等 catter 读取它。</td></tr><tr><td><code>eslogger</code></td><td>Endpoint Security 给出的每次 exec 和退出的时间。它只观察：构建像没有 catter 时那样运行。</td></tr><tr><td><code>--from</code></td><td>文件记录的时间，单位为微秒：事件的 <code>execution</code> 中有它的 <code>start</code>（从会话开始算起）和 <code>duration</code>。文件没有记录的时间为 <code>0</code>。</td></tr></tbody></table><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li><strong>识别串行化瓶颈</strong> -- 发现有可用核心时构建仍一次只运行一条命令的阶段：<code>running</code> 计数器降到 1。</li><li><strong>衡量实际并行度</strong> -- 把同时运行的命令数与核心数、以及构建工具得到的 <code>-j</code> 相比较。</li><li><strong>定位慢速编译单元</strong> -- 找到编译耗时不成比例的源文件，以及关键路径上的源文件。</li><li><strong>调试构建系统配置</strong> -- 检测错误的依赖配置、不必要的串行化或次优的任务调度。</li></ul>`,23)])])}const u=t(r,[["render",d]]);export{g as __pageData,u as default};
